static int count=0;
static void check(bool b,const char* s){printf("%s %s\n",b?"PASS":"FAIL",s);fflush(stdout);if(!b)ExitProcess(1);++count;}
static void put(const std::wstring&p,const std::wstring&s){FILE*f=_wfopen(p.c_str(),L"wb");check(f!=nullptr,"fixture handle");WORD bom=0xfeff;fwrite(&bom,2,1,f);fwrite(s.data(),2,s.size(),f);fclose(f);}
static std::vector<BYTE> bytes(const std::wstring&p){FILE*f=_wfopen(p.c_str(),L"rb");if(!f)return {};fseek(f,0,SEEK_END);auto n=ftell(f);rewind(f);std::vector<BYTE>b(n);fread(b.data(),1,n,f);fclose(f);return b;}
static COLORREF pixel(const std::wstring&p,int x,int y){HICON i=(HICON)LoadImageW(nullptr,p.c_str(),IMAGE_ICON,128,128,LR_LOADFROMFILE);check(i!=nullptr,"load generated multi-size icon");ICONINFO info{};GetIconInfo(i,&info);BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=128;bi.bmiHeader.biHeight=-128;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;std::vector<BYTE>b(128*128*4);HDC dc=GetDC(nullptr);check(GetDIBits(dc,info.hbmColor,0,128,b.data(),&bi,DIB_RGB_COLORS)==128,"read icon frame");ReleaseDC(nullptr,dc);DeleteObject(info.hbmMask);DeleteObject(info.hbmColor);DestroyIcon(i);auto q=&b[(y*128+x)*4];return RGB(q[2],q[1],q[0]);}
