 auto a=baseDir+L"\\Source 中文 & test",desk=baseDir+L"\\Desktop",file=baseDir+L"\\file.txt",lnk=baseDir+L"\\fake.lnk";CreateDirectoryW(a.c_str(),nullptr);CreateDirectoryW(desk.c_str(),nullptr);put(file,L"payload");put(lnk,L"not a real directory");put(a+L"\\keep.txt",L"original payload");auto payload=bytes(a+L"\\keep.txt");auto attrs=GetFileAttributesW(a.c_str());put(iniPath,L"[General]\r\nResident=0\r\n[Appearance]\r\nFollowDesktop=0\r\nFollowDesktopFont=0\r\n[Unknown]\r\nKeep=yes\r\n");loadConfig();
 check(EntryActions::realFolder(a),"real folder eligible");check(!EntryActions::realFolder(file)&&!EntryActions::realFolder(lnk),"file and shortcut not eligible");
 FolderRules::set(folderRules,a,false,true);std::wstring error;
 check(EntryActions::setPanelExpansion(a,true,error),"enable panel expansion");loadConfig();check(FolderRules::contains(folderRules,a,false)&&FolderRules::contains(folderRules,a,true),"persist panel flag without losing desktop flag");
 auto stale=folderRules;check(EntryActions::setPanelExpansion(a,false,error),"disable panel expansion");auto merged=EntryActions::mergeDesktopRules(folderRules,stale);check(!FolderRules::contains(merged,a,false)&&FolderRules::contains(merged,a,true),"stale settings draft cannot restore panel flag");
 auto iniBefore=bytes(iniPath);SetFileAttributesW(iniPath.c_str(),FILE_ATTRIBUTE_READONLY);check(!EntryActions::setPanelExpansion(a,true,error),"readonly config rejects toggle");check(!FolderRules::contains(folderRules,a,false)&&bytes(iniPath)==iniBefore&&!error.empty(),"failed toggle rolls memory and disk back");SetFileAttributesW(iniPath.c_str(),FILE_ATTRIBUTE_NORMAL);check(!EntryActions::setPanelExpansion(file,true,error),"toggle rejects plain file");
 // Creating a link never edits the source, and a preexisting same-name link is protected.
 auto existing=desk+L"\\Source 中文 & test.lnk";put(existing,L"unrelated existing shortcut");auto existingBytes=bytes(existing);std::wstring output;
 check(EntryActions::createDesktopEntry(a,desk,output,error),"create arbitrary-folder desktop entry");check(output!=existing&&bytes(existing)==existingBytes,"same-name desktop file not overwritten");check(entries.size()==4,"new managed entry in memory");auto entry=entries.back();
  std::wstring duplicate;auto entryCount=entries.size();check(EntryActions::createDesktopEntry(a,desk,duplicate,error),"duplicate source is accepted idempotently");check(duplicate.empty()&&entries.size()==entryCount,"duplicate source does not create a second desktop entry");
  loadConfig();check(entries.size()==4&&entries.back().id==entry.id&&entries.back().target==a,"new entry reloads for desktop hook and cold launch");
 IShellLinkW*sl=nullptr;IPersistFile*pf=nullptr;check(SUCCEEDED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&sl))),"create COM link reader");sl->QueryInterface(IID_PPV_ARGS(&pf));check(SUCCEEDED(pf->Load(output.c_str(),STGM_READ)),"generated link readable");wchar_t target[32768]{},args[512]{},icon[32768]{},work[32768]{};int ix;sl->GetPath(target,32768,nullptr,SLGP_RAWPATH);sl->GetArguments(args,512);sl->GetIconLocation(icon,32768,&ix);sl->GetWorkingDirectory(work,32768);pf->Release();sl->Release();check(exePath==target&&std::wstring(args)==L"--entry "+entry.id&&baseDir==work,"shortcut target arguments and working directory");check(std::wstring(icon)==entry.icon&&ix==0,"shortcut uses own generated icon");check(pixel(icon,120,20)==RGB(29,106,177),"generated shortcut blue badge");check(GetFileAttributesW((a+L"\\desktop.ini").c_str())==INVALID_FILE_ATTRIBUTES&&GetFileAttributesW(a.c_str())==attrs&&bytes(a+L"\\keep.txt")==payload,"creating shortcut never changes source metadata or payload");
 check(!EntryActions::createDesktopEntry(file,desk,output,error),"entry creation rejects file");check(!EntryActions::createDesktopEntry(a,baseDir+L"\\missing",output,error),"entry creation rejects missing desktop");
